/* === ACTIVE JAVASCRIPT IMPLEMENTATION === */
const results = ($input.first()?.json || []);
const rows = Array.isArray(results) ? results : (results.results || [results]);
const triggerData = $('Execute Workflow Trigger').first()?.json || {};
const locale = triggerData.locale || 'ar';
const isAr = locale === 'ar';
const customerMsg = triggerData.customer_message || triggerData.sanitized_message || '';

// T7: Normalize query for display (strip Arabic punctuation)
function normalizeAr(text) {
  return (text || '').replace(/[\u060c\u061b\u061c\u061d\u061e\u061f\u0621\u0622\u0623\u0624\u0625\u0626\u0627\u0628\u0629\u062a\u062f\u0648\u064a\u0646\u0629\u0647\u0649]/g, '');
}

// Filter results with relevance > 0
const relevant = rows.filter(r => r && r.relevance_score > 0);

// T3: Confidence classification based on actual score distributions
function classifyConfidence(score) {
  if (score >= 5) return 'high';
  if (score >= 3) return 'medium';
  if (score >= 1) return 'low';
  return 'none';
}

function confidenceLabel(score) {
  const c = classifyConfidence(score);
  return c.toUpperCase();
}

if (relevant.length > 0) {
  const sorted = [...relevant].sort((a, b) => (b.relevance_score || 0) - (a.relevance_score || 0));
  const top = sorted[0];
  const topScore = top.relevance_score || 0;
  const confidence = classifyConfidence(topScore);

  // Build context from top matching FAQ entries (prioritize high confidence)
  const contextParts = sorted.map(kb => {
    const q = isAr ? (kb.question_ar || kb.question) : (kb.question || kb.question_ar);
    const a = isAr ? (kb.answer_ar || kb.answer) : (kb.answer || kb.answer_ar);
    return `سؤال: ${q}\nإجابة: ${a}`;
  });
  const context = contextParts.join('\n---\n');

  // T6: Post-generation validation - check for policy-sensitive fields in context
  const contextText = context.toLowerCase();
  const policyTerms = ['رسوم', 'fee', 'سعر', 'price', 'مبلغ', 'amount', 'تاريخ', 'date', 'موعد', 'deadline'];
  const hasPolicyTerm = policyTerms.some(t => contextText.includes(t));

  return [{
    json: {
      status: 'rag_context_found',
      intent_handled: 'faq_query',
      rag_context: context,
      customer_message: customerMsg,
      locale: locale,
      top_category: top.category || 'general',
      relevance_score: topScore,
      confidence_score: topScore,
      confidence: confidence,
      confidence_label: confidenceLabel(topScore),
      retrieval_status: 'context_found',
      matched_entries: sorted.length,
      keyword_match_count: top.keyword_match_count || 0,
      content_match_count: top.content_match_count || 0,
      top_entry_id: top.id || null,
      validation: {
        status: hasPolicyTerm ? 'needs_review' : 'passed',
        policy_terms_detected: hasPolicyTerm ? policyTerms.filter(t => contextText.includes(t)) : []
      }
    }
  }];
} else {
  return [{
    json: {
      status: 'no_context',
      intent_handled: 'faq_query',
      rag_context: '',
      customer_message: customerMsg,
      locale: locale,
      relevance_score: 0,
      confidence_score: 0,
      confidence: 'none',
      confidence_label: 'NONE',
      retrieval_status: 'no_context',
      matched_entries: 0,
      validation: {
        status: 'no_context',
        reason: 'no_relevant_kb_entry'
      }
    }
  }];
}

const ragData = $('Format RAG Knowledge Response').first()?.json || {};
const qwenOutput = $input.first()?.json || {};
const locale = ragData.locale || 'ar';
const isAr = locale === 'ar';

// T4: Confidence-based guardrail decisions
const confidence = ragData.confidence || 'none';
const relevanceScore = ragData.relevance_score || 0;
const retrievalStatus = ragData.retrieval_status || 'no_context';

// T4: Define safe responses per confidence level
const safeFallbackAR = 'شكراً على استفسارك. لا أستطيع الإجابة على هذا الاستفسار بناءً على المعلومات المتاحة لدينا. يرجى التواصل مع فريق الدعم الرسمي عبر info@depi.gov.eg للحصول على مساعدة إضافية.';
const safeFallbackEN = 'Thank you for your question. I am unable to answer this based on our available information. Please contact our official support team at info@depi.gov.eg for further assistance.';
const clarificationAR = 'شكراً لاستفسارك. هل يمكنك توضيح سؤالك بشكل أكثر تحديداً؟ هل تقصد أحد المواضيع التالية: الشروط، التسجيل، المسارات، الامتحانات، أو المزايا؟';
const clarificationEN = 'Thank you for your question. Could you clarify your question more specifically? Are you asking about one of these: admission requirements, registration, tracks, exams, or benefits?';

let finalReply = '';
let guardrailDecision = 'escalation';

// T4: NONE/LOW confidence - hard deflection (no LLM response)
if (confidence === 'none' || confidence === 'low') {
  if (isAr) {
    finalReply = safeFallbackAR;
  } else {
    finalReply = safeFallbackEN;
  }
  guardrailDecision = 'hard_deflection';
}
// T4: MEDIUM confidence - clarification preferred
else if (confidence === 'medium') {
  // If LLM generated a response and validation passed, use it
  if (qwenOutput.response && ragData.validation && ragData.validation.status === 'passed') {
    finalReply = qwenOutput.response;
    guardrailDecision = 'llm_with_review';
  } else {
    finalReply = isAr ? clarificationAR : clarificationEN;
    guardrailDecision = 'clarification';
  }
}
// T4: HIGH confidence - allow grounded answer
else if (confidence === 'high') {
  // Post-generation validation check (T6)
  const validationStatus = ragData.validation ? ragData.validation.status : 'unknown';
  if (validationStatus === 'passed') {
    finalReply = qwenOutput.response || ragData.rag_context || '';
    guardrailDecision = 'grounded_llm';
  } else {
    // Validation failed or needs review - use fallback
    finalReply = safeFallbackAR;
    guardrailDecision = 'validation_failed_fallback';
  }
}
// Default fallback
else {
  finalReply = isAr ? safeFallbackAR : safeFallbackEN;
  guardrailDecision = 'default_fallback';
}

// Clean up markdown artifacts for WhatsApp
finalReply = finalReply.replace(/\*\*/g, '*').replace(/^#+\s*/gm, '').trim();

// T6: Build validation metadata
const validationMetadata = {
  status: guardrailDecision === 'grounded_llm' ? 'passed' : guardrailDecision,
  confidence: confidence,
  relevance_score: relevanceScore,
  guardrail_decision: guardrailDecision,
  retrieval_status: retrievalStatus
};

return [{
  json: {
    status: confidence === 'none' || confidence === 'low' ? 'escalation' : (guardrailDecision === 'grounded_llm' ? 'success' : 'clarification_required'),
    intent_handled: 'faq_query',
    category: ragData.top_category || 'general',
    reply: finalReply,
    sources: confidence === 'none' || confidence === 'low' ? ['DEPI Official Support - escalation'] : ['DEPI Official Knowledge Base - ' + (ragData.top_category || 'General')],
    validation: validationMetadata,
    confidence: confidence,
    confidence_label: ragData.confidence_label || 'N/A',
    guardrail_decision: guardrailDecision
  }
}];
